/* Source-aligned Bloxy Cola client module. Public original asset bytes are used as data only; the Roblox script is never executed. */
(() => {
  'use strict';

  const MESH_B64 = '';
  const ICON_URL = 'assets/bloxycola-10472127.png?id=10472127';
  const TEXTURE_URL = 'assets/bloxycola-10470600.png?id=10470600';
  const OPEN_SOUND_URL = 'assets/bloxycola-10721950.ogg?id=10721950';
  const DRINK_SOUND_URL = 'assets/bloxycola-10722059.ogg?id=10722059';
  let parsedGeometry = null;

  function geometry() {
    if (parsedGeometry) return parsedGeometry;
    const binary = (window.atob || atob)(MESH_B64);
    const bytes = Uint8Array.from(binary, ch => ch.charCodeAt(0));
    const source = new TextDecoder().decode(bytes);
    const lines = source.split(/\r?\n/);
    if (lines[0] !== 'version 1.00') throw new Error('Original Cola mesh version mismatch');
    const faceCount = Number(lines[1]);
    const records = [...lines.slice(2).join('\n').matchAll(/\[([^\]]+)\]/g)];
    if (!Number.isInteger(faceCount) || faceCount !== 144 || records.length !== faceCount * 9) {
      throw new Error('Original Cola mesh record count mismatch');
    }
    const vectors = records.map(m => m[1].split(',').map(Number));
    if (vectors.some(v => v.length !== 3 || v.some(n => !Number.isFinite(n)))) {
      throw new Error('Invalid original Cola mesh vector');
    }
    const vertices = [], uvs = [];
    for (let face = 0; face < faceCount; face++) {
      for (let vertex = 0; vertex < 3; vertex++) {
        const i = face * 9 + vertex * 3;
        const p = vectors[i], n = vectors[i + 1], uv = vectors[i + 2];
        // The source SpecialMesh scale is 1.2; the project renderer uses the
        // same v1.00 half-unit conversion as AvatarAssets.meshGeometry.
        vertices.push(p[0] * 0.6, p[1] * 0.6, p[2] * 0.6, n[0], n[1], n[2]);
        uvs.push(uv[0], 1 - uv[1]);
      }
    }
    parsedGeometry = Object.freeze({
      vertices: new Float32Array(vertices),
      uvs: new Float32Array(uvs),
      count: vertices.length / 6,
      vertexCount: vertices.length / 6,
      sourceAssetId: 10470609
    });
    return parsedGeometry;
  }

  const gripDefault = Object.freeze({
    forward: [-0.976, 0, -0.217], position: [0.03, 0, 0],
    right: [0.217, 0, -0.976], up: [0, 1, 0]
  });
  const gripDrink = Object.freeze({
    forward: [0, -0.759, -0.651], position: [1.5, -0.5, 0.3],
    right: [1, 0, 0], up: [0, 0.651, -0.759]
  });
  const grip = Object.freeze({
    position: gripDefault.position,
    rotation: [0.217036352,0,0.976163507,0,1,0,-0.976163507,0,0.217036352]
  });
  const gripDrinkCFrame = Object.freeze({
    position: gripDrink.position,
    rotation: [1,0,0,0,0.651,0.759,0,-0.759,0.651]
  });
  window.BloxyColaData = Object.freeze({
    toolName: 'Bloxy Cola', assetId: 10472779, modelAssetId: 10472779,
    meshAssetId: 10470609, textureAssetId: 10470600, iconAssetId: 10472127,
    openSoundAssetId: 10721950, drinkSoundAssetId: 10722059,
    iconData: ICON_URL, textureData: TEXTURE_URL,
    openSoundUrl: OPEN_SOUND_URL, drinkSoundUrl: DRINK_SOUND_URL,
    meshScale: Object.freeze([1.2, 1.2, 1.2]),
    gripDefault, gripDrink, grip, gripDrinkCFrame, geometry
  });

  const IDENTITY = [1,0,0,0,1,0,0,0,1];
  const COLORS = {
    blue: [0.035,0.26,0.67,1], darkBlue: [0.015,0.12,0.38,1],
    yellow: [1,0.86,0.025,1], silver: [0.72,0.76,0.79,1],
    highlight: [0.9,0.93,0.95,1]
  };
  function draw(frame, box, A) {
    if (!frame || typeof box !== 'function' || !A?.multiply || !A?.fromCFrame) return;
    const part = (size, offset, color) => {
      const local = A.fromCFrame({ position: offset, rotation: IDENTITY });
      box(size, A.multiply(frame, local), color);
    };
    // Fallback only; the main renderer uses the original mesh and texture above.
    part([0.52,1.12,0.48],[0,0,0],COLORS.blue);
    part([0.54,0.075,0.50],[0,0.59,0],COLORS.silver);
    part([0.49,0.045,0.45],[0,0.65,0],COLORS.highlight);
    part([0.15,0.025,0.10],[0.035,0.685,0],COLORS.silver);
    part([0.34,0.40,0.035],[0,-0.01,-0.247],COLORS.yellow);
    for (const y of [-0.14,-0.06,0.02,0.10]) part([0.045,0.055,0.045],[-0.09,y,-0.273],COLORS.darkBlue);
    part([0.42,0.045,0.40],[0,-0.59,0],COLORS.darkBlue);
  }

  function create(ctx = {}) {
    let pending = false, drinking = false, retryAt = 0, drinkStartedAt = 0, drinkDurationMs = 3000;
    let token = null, timeout = 0, finishTimer = 0, phase = 'idle', activeReqId = 0, reqSerial = 0;
    const startTimeoutMs = Number.isFinite(ctx.startTimeoutMs) ? Math.max(100, ctx.startTimeoutMs) : 65000;
    const finishTimeoutMs = Number.isFinite(ctx.finishTimeoutMs) ? Math.max(100, ctx.finishTimeoutMs) : 10000;
    const now = () => typeof performance !== 'undefined' ? performance.now() : Date.now();
    function playAsset(url) {
      try {
        if (!url) return;
        if (typeof ctx.playSound === 'function') { ctx.playSound(url); return; }
        if (typeof window.Audio !== 'function') return;
        const audio = new window.Audio(url); audio.preload = 'auto';
        const p = audio.play(); if (p?.catch) p.catch(() => {});
      } catch (_) { /* audio is optional */ }
    }
    function clearPending() {
      pending = false; drinking = false; token = null; phase = 'idle'; activeReqId = 0;
      clearTimeout(timeout); clearTimeout(finishTimer); timeout = finishTimer = 0;
    }
    function reject(result) {
      clearPending();
      const remaining = Math.max(0, Number(result?.remainingMs) || 0);
      if (remaining) retryAt = Math.max(retryAt, now() + remaining);
      try { ctx.onRejected?.(result); } catch (_) {}
    }
    function accepted(result) {
      clearPending(); retryAt = now() + Math.max(0, Number(result?.cooldownMs) || 0);
      try { ctx.onAccepted?.(result); } catch (_) {}
    }
    function finishOffline() {
      finishTimer = 0;
      let result; try { result = ctx.healOffline?.(); } catch (_) { result = null; }
      if (result?.accepted === true) accepted({ ...result, cooldownMs: 0 }); else reject(result || { accepted:false, reason:'unavailable' });
    }
    function sendFinish() {
      finishTimer = 0;
      const reqId = activeReqId, finishToken = token;
      phase = 'completing';
      let sent = false; try { sent = ctx.finishUse?.(finishToken, reqId) === true; } catch (_) { sent = false; }
      if (!sent) { reject({ accepted:false, reason:'finish-send-failed' }); return; }
      timeout = setTimeout(() => { if (activeReqId === reqId && phase === 'completing') reject({ accepted:false, reason:'timeout' }); }, finishTimeoutMs);
    }
    function cancel() {
      const hadOnline = pending && ctx.isOnline?.(), cancelReqId=activeReqId, cancelToken=token;
      clearPending();
      if (hadOnline) { try { ctx.sendCancel?.(cancelReqId,cancelToken); } catch (_) {} }
    }
    function equip() { playAsset(OPEN_SOUND_URL); }
    function use() {
      if (pending || now() < retryAt) return false;
      if (ctx.isOnline?.()) {
        const reqId = ++reqSerial;
        pending = true; phase = 'starting'; activeReqId = reqId; token = null;
        let sent = false; try { sent = ctx.sendUse?.(reqId) === true; } catch (_) { sent = false; }
        if (!sent) { clearPending(); return false; }
        timeout = setTimeout(() => { if (activeReqId === reqId && phase === 'starting') reject({ accepted:false, reason:'timeout' }); }, startTimeoutMs);
        return true;
      }
      pending = true; phase = 'drinking'; drinking = true; drinkStartedAt = now(); drinkDurationMs = 3000; playAsset(DRINK_SOUND_URL);
      try { ctx.onDrinkStart?.({ startedAt:drinkStartedAt, durationMs:drinkDurationMs }); } catch (_) {}
      finishTimer = setTimeout(finishOffline, drinkDurationMs);
      return true;
    }
    function onResult(result) {
      if (!result || !pending) return;
      if (result.reqId !== undefined && result.reqId !== activeReqId) return;
      if (result.accepted !== true) {
        if (result.stage === 'started' && phase !== 'starting') return;
        if (result.stage === 'complete' && phase !== 'completing') return;
        reject(result); return;
      }
      if (result.stage === 'started') {
        if (phase !== 'starting') return;
        clearTimeout(timeout); timeout = 0;
        if (!Number.isFinite(result.token) && typeof result.token !== 'string') { reject({ accepted:false, reason:'invalid-token' }); return; }
        token = result.token; phase = 'drinking';
        drinkDurationMs = Number.isFinite(result.durationMs) ? Math.max(0,Math.min(3000,result.durationMs)) : 3000;
        drinking = true; drinkStartedAt = now(); playAsset(DRINK_SOUND_URL);
        try { ctx.onDrinkStart?.({ startedAt:drinkStartedAt, durationMs:drinkDurationMs }); } catch (_) {}
        finishTimer = setTimeout(sendFinish, drinkDurationMs);
        return;
      }
      if (result.stage === 'complete') {
        if (phase !== 'completing') return;
        if (result.token !== undefined && result.token !== token) return;
        accepted(result); return;
      }
      reject({ accepted:false, reason:'unsupported-protocol' });
    }
    function getState() {
      const elapsed = drinking ? Math.max(0, now() - drinkStartedAt) : 0;
      return { pending, drinking, phase, drinkDurationMs, drinkProgress: drinking ? Math.min(1, elapsed / Math.max(1,drinkDurationMs)) : 0, retryInMs: Math.max(0,retryAt-now()) };
    }
    return Object.freeze({ use, equip, cancel, onResult, getState });
  }

  window.BloxyCola = Object.freeze({ create, draw });
})();
